let n = 0;
for (let i = 2; i <= 19; i++) {
  const v = wb.getRange(`Before!G${i}`).getCell().getValue();
  if (typeof v === 'number') {
    const k = wb.getRange(`Before!K${i}`);
    k.setValue(v);
    k.getStyle().setNumberFormat('d-mmm');
    n++;
  }
}
const out: any[] = [];
for (let i = 2; i <= 19; i++) {
  const k = wb.getRange(`Before!K${i}`).getCell();
  const a = wb.getRange(`After!K${i}`).getCell();
  out.push([i, k.getValue(), k.getText(), k.getValue() === a.getValue()]);
}
JSON.stringify({ n, out, g: wb.getRange('Before!G2:G19').getStats ? undefined : undefined })

